CREATE OR REPLACE FUNCTION public.claim_push_delivery(_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE j public.push_delivery_jobs; used integer; BEGIN SELECT * INTO j FROM public.push_delivery_jobs WHERE id = _id; IF NOT FOUND THEN RETURN false; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(j.subscription_id::text || j.layer || j.day::text, 0)); SELECT COALESCE(sum(attempts), 0) INTO used FROM public.push_delivery_jobs WHERE subscription_id = j.subscription_id AND layer = j.layer AND day = j.day; IF used >= 3 THEN RETURN false; END IF; UPDATE public.push_delivery_jobs SET attempts = attempts + 1, lease_until = now() + interval '1 minute' WHERE id = _id AND status = 'pending' AND attempts < 3 AND (lease_until IS NULL OR lease_until < now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_push_delivery(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_push_delivery(uuid) TO service_role;